import pyomo.environ as pyo

DATA = {
    "num_centers": 5,
    "num_stores": 9,
    "opening_cost": [151000, 192000, 114000, 171000, 160000],
    "transport_cost": [
        [5, 2, 3, 3, 3, 5, 4, 3, 5],
        [2, 4, 2, 4, 5, 1, 4, 2, 5],
        [4, 1, 1, 3, 3, 2, 4, 4, 3],
        [4, 4, 1, 3, 5, 3, 5, 1, 2],
        [4, 1, 4, 2, 2, 1, 2, 5, 2],
    ],
    "demand": [739, 491, 766, 854, 827, 908, 434, 605, 480],
    "capacity": [1825, 1821, 1365, 1929, 1502],
}


def build_model(data=None):
    d = data or DATA

    m = pyo.ConcreteModel()

    m.I = pyo.RangeSet(0, d["num_centers"] - 1)
    m.J = pyo.RangeSet(0, d["num_stores"] - 1)

    def _oc(i):
        return d["opening_cost"][i]

    def _tc(i, j):
        return d["transport_cost"][i][j]

    def _dem(j):
        return d["demand"][j]

    def _cap(i):
        return d["capacity"][i]

    # y[i] = 1 if center i is opened (binary: opening decision is indivisible)
    m.y = pyo.Var(m.I, within=pyo.Binary)

    # x[i,j] = flow of units from center i to store j (continuous per the text)
    m.x = pyo.Var(m.I, m.J, within=pyo.NonNegativeReals)

    def obj_rule(m):
        return sum(_oc(i) * m.y[i] for i in m.I) + sum(
            _tc(i, j) * m.x[i, j] for i in m.I for j in m.J
        )

    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def demand_rule(m, j):
        return sum(m.x[i, j] for i in m.I) >= _dem(j)

    m.demand_con = pyo.Constraint(m.J, rule=demand_rule)

    def capacity_rule(m, i):
        return sum(m.x[i, j] for j in m.J) <= _cap(i) * m.y[i]

    m.capacity_con = pyo.Constraint(m.I, rule=capacity_rule)

    return m


